 d['vocabulary']=[dict(term=t,meaning=m) for t,m in [('population','Organisms of one species in a particular area.'),('community','Populations of different species living in an area.'),('ecosystem','A community interacting with the non-living environment.'),('biotic','Living components and effects of organisms, such as predation.'),('abiotic','Non-living environmental factors, such as light or moisture.'),('biodiversity','The variety of life; here we compare species richness as one aspect.'),('species richness','The number of different species present in a stated sample.'),('abundance','The number of individuals present in a stated sample.')]]
 d['safety']=['The complete route uses printed evidence at desks. No live animals, plants or soil need handling.','Optional follow-up sampling stays within an agreed accessible area; pupils do not taste plants, handle unknown organisms or disturb nests. Wash hands after outdoor work.']
 d['practicalAlternative']='Use the supplied fictional garden web and matched-area constructed count data. Pupils can make a complete evidence brief within 40 minutes without collecting outdoor samples.'
 d['preparation']+=['Explain that the food web is a simplified garden model and the counts come from a separate plant-sampling task. They are not measurements of the animals in the web.']
 d['misconceptions']=[dict(claim=c,correction=k,check=q) for c,k,q in [('An ecosystem is just a list of animals.','It includes the community, non-living environment and their interactions.','Ask where light and soil moisture fit.'),('Food-web arrows show the predator pointing at its prey.','Arrows show transfer of material and energy from food to consumer.','Read leaf→aphid aloud.'),('Twenty organisms always means greater biodiversity than ten.','Abundance alone does not tell us how many species are present.','Compare two samples that both contain twenty plants.'),('One sample proves that a mowing regime caused the difference.','Sampling can vary; other conditions may differ. Repeat comparable sampling and use a fair design before causal claims.','Ask what the sample comparison cannot establish.')]]
 d['access']=dict(supported='Supply short vocabulary choices, an arrow sentence and counts to circle. Accept a labelled evidence map plus spoken reason.',standard='Create a garden brief linking environment, feeding relationships and sample evidence.',stretch='Evaluate sampling limits and propose matched repeated measurements to test a maintenance decision. No diversity-index calculation required.',regulation='Use a fictional garden decision. Allow quiet written votes and private review. Choose route from retrieval and hinge responses; pupils can change route when appropriate.')
